# -*- coding: utf-8 -*-
"""Concept bank for the repaired ARIA dataset.

Every entry is one *concept family* (the unit used for splitting, so a concept
never appears in two splits). Fields:

  key       stable id, also the split family key
  course    controlled-vocabulary course title (drives `course` and `domain`)
  topic     human topic label
  rubric    3-6 independent, checkable points, each paired with a student
            phrasing that genuinely earns it (used to build honest grading)
  misconception  the wrong IDEA, named in the tutor's own words
  wrong     a student answer that expresses that wrong idea
  rfwr      (answer, why) right conclusion reached by wrong reasoning
  vague     an answer too thin to grade -> unanswerable/ambiguous verdict
  offtopic  a plausible but off-topic answer
  correction  the concrete fix
  mechanism   one sentence of why it works that way
  followup    a task that targets this specific error
  probe       opening Socratic question (attempts 1-3)
  hint        targeted hint (attempts 4-7)
  worked      worked explanation (attempt 8+ / earned reveal)
  variant     transfer task after the reveal
  records     2-3 verbatim course-record lines (id, text) with real content
  stale       an older record line that conflicts with the current one
  keywords    grading keywords
"""


def C(key, course, topic, rubric, misconception, wrong, rfwr, vague, offtopic,
      correction, mechanism, followup, probe, hint, worked, variant, records,
      stale, keywords):
    return dict(key=key, course=course, topic=topic, rubric=rubric,
                misconception=misconception, wrong=wrong, rfwr=rfwr, vague=vague,
                offtopic=offtopic, correction=correction, mechanism=mechanism,
                followup=followup, probe=probe, hint=hint, worked=worked,
                variant=variant, records=records, stale=stale, keywords=keywords)


